351: function drawArmsAndWeapon(ctx, o, pal, skin, attack, casting, time, swing) {
352:   const eq = o.equipment || {};
353:   const cls = o.classId;
354:   const weapon = eq.weapon;
355:   const wRar = weapon?.rarity || 'common';
356:   const wColor = EQUIP_COLOR(wRar, pal.metal);
357:   const gloveColor = eq.gloves ? EQUIP_COLOR(eq.gloves.rarity, pal.metal2) : pal.metal2;
358:   const atkSwing = attack > 0 ? Math.sin(attack * Math.PI) : 0;
359: 
360:   if (cls === 'warrior') {
361:     // back arm
362:     p(ctx, -9, -27, 3, 9 + Math.round(swing), pal.metal2);
363:     p(ctx, -9, -19 + Math.round(swing), 3, 3, gloveColor);
364:     // weapon pivot at shoulder, swing forward
365:     ctx.save();
366:     ctx.translate(6, -26);
367:     ctx.rotate(-0.5 - atkSwing * 2.4 + Math.sin(time * 2) * 0.02);
368:     // arm
369:     p(ctx, -1, 0, 3, 10, pal.metal2);
370:     p(ctx, -1, 8, 3, 3, gloveColor);
371:     // hilt
372:     p(ctx, -1, 10, 2, 6, '#4a3324');
373:     p(ctx, -4, 15, 8, 2, pal.trim);
374:     px(ctx, 0, 16, '#7a5a2e');
375:     // blade
376:     p(ctx, -2, -24, 4, 36, shade(wColor, 0.12));
377:     p(ctx, -1, -25, 2, 3, '#e8f4ff');
378:     p(ctx, -3, 8, 6, 3, wColor);
379:     p(ctx, -1, 11, 2, 2, '#7a5a2e');
380:     if (wRar !== 'common' && wRar !== 'grey') {
381:       p(ctx, -1, -22, 1, 28, RARITIES[wRar].glow);
382:     }
383:     ctx.restore();
384:   } else if (cls === 'mage') {
385:     p(ctx, -9, -27, 3, 9, pal.cloth2);
386:     p(ctx, -9, -18, 3, 3, skin);
387:     ctx.save();
388:     ctx.translate(7, -25);
389:     ctx.rotate(-0.08 - atkSwing * 0.4);
390:     p(ctx, -1, 0, 3, 9, pal.cloth2);
391:     p(ctx, -1, 8, 3, 3, skin);
392:     // staff
393:     const staffTop = casting || attack > 0 ? -22 - atkSwing * 4 : -24;
394:     p(ctx, 0, staffTop, 2, 44, '#5a3f27');
395:     p(ctx, -1, staffTop + 2, 4, 2, pal.trim);
396:     // orb
397:     const orbC = casting ? pal.trim : wColor;
398:     p(ctx, -3, staffTop - 5, 7, 7, shade(orbC, -0.2));
399:     p(ctx, -2, staffTop - 6, 5, 9, orbC);
400:     p(ctx, -1, staffTop - 5, 2, 3, shade(orbC, 0.35));
401:     if (casting) {
402:       ctx.globalAlpha = 0.5 + Math.sin(time * 12) * 0.2;
403:       p(ctx, -5, staffTop - 8, 11, 13, pal.trim);
404:     }
405:     ctx.restore();
406:   } else {
407:     p(ctx, -9, -27, 3, 9, pal.cloth2);
408:     p(ctx, -9, -18, 3, 3, skin);
409:     // bow in front hand
410:     ctx.save();
411:     ctx.translate(9, -24);
412:     ctx.rotate(-0.1 - atkSwing * 0.25);
413:     p(ctx, -1, 0, 2, 9, pal.cloth2);
414:     p(ctx, -1, 8, 2, 3, skin);
415:     // bow limb
416:     const bc = shade(pal.metal, 0.1);
417:     p(ctx, 0, -12, 2, 6, bc);
418:     p(ctx, 1, -6, 2, 12, bc);
419:     p(ctx, 0, 6, 2, 6, bc);
420:     p(ctx, 2, -10, 1, 4, pal.trim);
421:     p(ctx, 2, 5, 1, 4, pal.trim);
422:     // string (pulled when attacking)
423:     ctx.strokeStyle = '#e9e2c8';
424:     ctx.lineWidth = 0.8;
425:     ctx.beginPath();
426:     ctx.moveTo(2, -11);
427:     ctx.lineTo(atkSwing > 0.2 ? -1 : 1.5, atkSwing > 0.2 ? -1 : 0);
428:     ctx.lineTo(2, 11);
429:     ctx.stroke();
430:     if (atkSwing > 0.2) {
431:       p(ctx, -1, -0.5, 24, 1, '#d9c58a');
432:       p(ctx, 22, -1.5, 2, 3, '#cfd8e2');
433:     }
434:     ctx.restore();
435:   }
436: 
437:   // front arm for non weapon side
438:   if (cls === 'mage') {
439:     p(ctx, 8, -27, 3, 9, pal.cloth2);
440:     p(ctx, 8, -18, 3, 3, skin);
441:   } else if (cls === 'archer') {
442:     p(ctx, -9, -26, 3, 9, pal.cloth2);
443:     p(ctx, -9, -17, 3, 3, gloveColor);
444:   }
445: }
