1065:       p(ctx, 3, -4, 3, 3, '#5d6068');
1066:       p(ctx, 1, -10, 3, 2, '#a6adb4');           // sun facet
1067:       if (v % 4 === 0) px(ctx, -2, -6, '#6b8a4f');   // moss
1068:       if (snow) {
1069:         p(ctx, -5, -11, 10, 2, '#eef6fa');
1070:         p(ctx, -3, -9, 5, 1, '#d7e6ef');
1071:       }
1072:       break;
1073:     }
1074:     case 'boulder': {
1075:       p(ctx, -10, -14, 20, 14, '#676b73');
