74: function markDisc(world, cx, cy, radius, type, onlyIf = null) {
75:   const r = Math.ceil(radius);
76:   for (let y = Math.floor(cy) - r; y <= Math.ceil(cy) + r; y++) {
77:     for (let x = Math.floor(cx) - r; x <= Math.ceil(cx) + r; x++) {
78:       if (!inBounds(world, x, y)) continue;
79:       if (Math.hypot(x + 0.5 - cx, y + 0.5 - cy) > radius) continue;
80:       const t = world.tiles[idx(world.size, x, y)];
81:       if (!t || t.type === 'water') continue;
82:       if (onlyIf && !onlyIf(t)) continue;
83:       setTile(world, x, y, type);
84:     }
85:   }
