107: export function child(file, args, { signal, killGraceMs = 5000, settleGraceMs = 1000, ...options } = {}) {
108:   return new Promise((resolve, reject) => {
109:     const started = Date.now()
110:     const proc = spawn(file, args, { stdio: ['ignore', 'inherit', 'pipe'], detached: process.platform !== 'win32', ...options })
111:     if (proc.pid) { children.add(proc); recordChildren() }
112:     let stderr = '', forced, deadline, settled = false
113:     proc.stderr?.on('data', chunk => { process.stderr.write(chunk); stderr = (stderr + chunk.toString()).slice(-4000) })
114:     const finish = error => {
115:       if (settled) return
116:       settled = true
117:       clearTimeout(forced); clearTimeout(deadline); signal?.removeEventListener('abort', abort)
118:       // Even if the leader exits first, terminate descendants in its detached group.
119:       if (signal?.aborted) signalChild(proc, 'SIGKILL')
120:       children.delete(proc); recordChildren()
121:       proc.stderr?.destroy()
122:       process.stderr.write(`[timing] ${file}: ${Date.now() - started} ms\n`)
123:       if (error) reject(error)
124:       else resolve()
125:     }
126:     const abort = () => {
127:       signalChild(proc, 'SIGTERM')
128:       forced = setTimeout(() => signalChild(proc, 'SIGKILL'), killGraceMs)
129:       // Do not depend on close: a descendant can retain the inherited stderr pipe.
130:       deadline = setTimeout(() => finish(new Error('Cancelled')), killGraceMs + settleGraceMs)
131:     }
132:     signal?.addEventListener('abort', abort, { once: true })
133:     if (signal?.aborted) abort()
134:     proc.once('error', finish)
135:     proc.once('close', code => {
136:       if (signal?.aborted) finish(new Error('Cancelled'))
137:       else if (code !== 0) finish(Object.assign(new Error(`${file} exited ${code}${stderr.trim() ? `: ${stderr.trim().slice(-1500)}` : ''}`), { exitCode: code }))
138:       else finish()
139:     })
140:   })
141: }
